var a={en:`A room has 10,000 watchers and 20 editors. Broadcasting every cursor move to everyone exhausts socket CPU and bandwidth.`,ua:`Кімната має 10 000 глядачів і 20 редакторів. Розсилання кожного руху курсора всім перевантажує CPU й мережу.`};var t={en:[`Separate low-priority ephemeral traffic from durable edits.`,`Propose selective fanout, throttling or coalescing.`,`Define edit-latency SLO and fanout metrics under load.`],ua:[`Відокрем низькопріоритетну присутність від постійних змін.`,`Запропонуй вибіркову розсилку, обмеження чи об’єднання подій.`,`Визнач SLO змін і метрики розсилання під навантаженням.`]};var o=[{en:`Edit reliability is independent of cursor traffic.`,ua:`Надійність редагувань не залежить від курсорів.`},{en:`Viewers do not require every high-frequency cursor event.`,ua:`Глядачам не потрібна кожна часта подія курсора.`}];var i={scenario:a,tasks:t,checks:o};export{o as checks,i as default,a as scenario,t as tasks};